import React from 'react';
import PropTypes from 'prop-types';

import { Tabs, TabLink, TabContent } from 'react-tabs-redux';
import LoadingSpinner from '../common/LoadingSpinner';

import {MODES} from '../../constants/commandeModes';

import LocalizedStrings from 'react-localization';
import {data} from '../../constants/translations';
import logger from '../../helpers/Logger';
let strings = new LocalizedStrings(data);


const ProduitBtn = ({ id, nom, prix, composition, color, onClick, disabled }) => (
  // <Button
  //   className="ProduitBtn"
  //   id={id}
  //   composition={ composition }
  //   onClick={ () => onClick(id) }
  // ><div>{ nom }</div><div>{ Number(prix).toFixed(2).replace('.',',') }&nbsp;€</div></Button>
  <div
    className={ `ProduitBtn${disabled ? ' btn-disabled' :''} ${color}` }
    id={id}
    composition={ composition }
    onClick={ () => {  if (!disabled) onClick(id)} }
  ><div className="btnlabel">
    <div className="nom">{ nom }</div>
    <div className="supplt">{ Number(prix).toFixed(2).replace('.',',') }&nbsp;€</div>
    </div>
  </div>
);


class Selecteur extends React.Component {

  // componentDidMount() {
  //   const { getAllActive } = this.props;
  //   getAllActive();
  // }

  // action on buttons (fill in passphrase)
  buttonHandler(text) {
    logger.info(`Produit #${text}`);
  }

  scrollTabBar(dir) {
    // if ('up'==dir) {
      
    // }
  }

  render() {

    const { catalogue, categories, error, loading, addProduit, mode } = this.props;
  
    let tlinks = [];
    let tcontents = [];

    const groupes = Object.values(catalogue).sort((a,b)=>a.weight-b.weight);
    
//    for (let [key, value] of Object.entries(catalogue)) {
    groupes.forEach(grp => {
      if (grp.categorie===categories[0].categorie_id) tlinks.push({id: grp.groupe_id, nom: grp.nom});
      grp.produits.sort((a,b)=> a.weight - b.weight); 
      tcontents.push({parent: grp.groupe_id, liste: grp.produits});
    });


    // organiser les prd par weight


    if(loading) {
      return <div className="SelecteurEmpty"><LoadingSpinner /></div>
    }

    if (undefined === catalogue) {
      return <div className="SelecteurEmpty">{ strings.modules.encaissement.selecteur.empty }</div>
    }
    
    return (
      <Tabs className="Selecteur">
        {error && <span className="error">{error}</span>}
        <div className="TabBar">
          {/* <div className="btn-up"></div> */}
            <div className="wrapper" ref={ this.barwrapper }>
              { tlinks.map(grp => 
              <TabLink to={ grp.id} key={grp.id}>{ grp.nom }</TabLink>
              )}
          </div>
          {/* <div className="btn-down"></div> */}
            
        </div>
        <div className="TabCont">
          {/* <div className="btn-up"></div> */}
          <div className="wrapper">
            { tcontents.map(cnt => 
            <TabContent for={ cnt.parent } key={cnt.parent}>
              { cnt.liste.map(prd => 
                <ProduitBtn 
                  key={ prd.id } 
                  id={ prd.id } 
                  nom={ prd.nom } 
                  prix={ prd.prixArray[MODES[mode]].ttc } 
                  color={ prd.color }
                  disabled={ prd.active===0 }
                  composition={prd.composition}
                  onClick={ () => addProduit({produitid: prd.id, nom: prd.nom, prix: Number(prd.prixArray[MODES[mode]].ttc), puht: Number(prd.prixArray[MODES[mode]].ht), composition: prd.composition, compo: prd.compo, customizable: prd.customizable, tva_id:prd.tvaArray[MODES[mode]] }) } />
              )}
            </TabContent>
            )}
          </div>
          {/* <div className="btn-down"></div> */}
        </div>
      </Tabs>
    );
  }
}
export default Selecteur;
  
Selecteur.propTypes = {
  catalogue: PropTypes.object,
  loading: PropTypes.bool,
  error: PropTypes.string,
  getAllActive: PropTypes.func,
  addProduit: PropTypes.func,
}